"""Read a layer-level overview generated by FM MCP."""

from typing import Any, Literal

from fm_mcp.profiling.service import get_overview


async def get_data_profiling_overview(
    layer: Literal["bronze", "silver", "gold"] = "bronze",
    year: int | None = None,
    month: int | None = None,
    include_demo: bool = False,
) -> dict[str, Any]:
    """Return latest quality scores, status counts, dimensions, and asset findings."""
    return await get_overview(layer, year, month, include_demo)
